import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  SimpleChanges,
} from '@angular/core';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { FileexplorerComponent } from '../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { ActivatedRoute, Router } from '@angular/router';
import { HeaderComponent } from '../../../core/headercomponents/header/header.component';
import { HeaderService } from '../../../core/services/header/header.service';
import {
  presentDocType,
  presentSetupData,
} from '../../interfaces/presentsetup';
import { choosedDocs } from '../../interfaces/choose-doc.interface';
import { PresentsetupService } from '../../services/presentsetup/presentsetup.service';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { IconComponent } from '../../../shared/components/icon/icon.component';
import { LocationStrategy } from '@angular/common';
import { UserPermissionService } from '../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-choose-docs',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [
    ButtonComponent,
    FileexplorerComponent,
    HeaderComponent,
    IconComponent,
  ],
  templateUrl: './choose-docs.component.html',
  styleUrl: './choose-docs.component.scss',
})
export class ChooseDocsComponent {
  nCaseid: string;
  nPresentid: string;
  nPCid: string | null;

  nContactid: string;
  presentDocType: presentDocType;

  isLoading: boolean = true;
  presentSession: presentSetupData | null = null;

  choosedDocs: choosedDocs[] = [];

  coreFiles: string[] = [];
  selectedFiles: any = {};
  selectedBundles: string[] = [];
  selectedBundleDetails: string[] = [];

  bIsfilePresent = false;

  bShowPresentHistory: boolean = false;
  constructor(
    private route: ActivatedRoute,
    private hs: HeaderService,
    private readonly PSservice: PresentsetupService,
    private cdr: ChangeDetectorRef,
    private cm: CommonfunctionService,
    private router: Router,
    private tost: TostbarService,
    private location: LocationStrategy,
    private userPermissions: UserPermissionService
  ) {
    var params = this.route.snapshot.params;
    if (Object.keys(params).length > 0) {
      params = JSON.parse(decodeURIComponent(params['id']));
      this.nCaseid = params && params['id'] ? params['id'] : null;
      hs.nCaseid = this.nCaseid;
      this.nContactid = params && params['cid'] ? params['cid'] : null;
      this.nPresentid = params['nPid'] || null;
      this.nPCid = params['nPCid'] || null;
    }
    hs.currentadminpath.next('my files');
    if (this.nCaseid) {
      hs.nCaseid = this.nCaseid;
    }

    // disable window history
    history.pushState(null, null, window.location.href);
    this.location.onPopState(() => {
      history.pushState(null, null, window.location.href);
    });

    userPermissions.userPermissionList(this.nCaseid);

  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['coreFiles']) {
      this.cdr.detectChanges();
    }
  }

  async ngOnInit() {
    if (this.nCaseid) {
      this.presentSession = await this.PSservice.getRvalue(this.nCaseid);
      this.presentDocType = this.presentSession?.cSType == 'W' ? 'CF' : this.presentSession?.cSType == 'C' ? 'C' : 'F';
    }

    this.isLoading = false;

    if (this.nPresentid) {
      this.getDetail();
    }
    this.cdr.detectChanges();
  }

  async getDetail() {
    try {
      const res = await this.PSservice.detail(this.nPresentid);
      this.coreFiles =
        res.filter((a) => a.cType == 'C').map((a) => a.nBundledetailid) || [];
      const scheduleFile = res.filter((a) => a.cType != 'C');

      this.selectedBundles = scheduleFile
        .filter((a) => a.nBundleid)
        .map((a) => a.nBundleid);

      this.selectedBundleDetails = scheduleFile
        .filter((a) => a.nBundledetailid)
        .map((a) => a.nBundledetailid);

      this.selectedFiles = {
        fileids: this.selectedBundleDetails.map((a) => {
          return { id: a, bid: 0 };
        }),
        fldrids: this.selectedBundles.map((a) => {
          return { id: a, bid: 0 };
        }),
      };

      this.cdr.detectChanges();
    } catch (error) { }
  }

  FileEvent(e) {
    if (e.event == 'GO-TO-PRESENT') {
      this.selectedFiles = e.data;
      this.selectedBundleDetails = e.data?.fileids.map((a) => a.id);
      this.submit();
    }
    // console.log('file event', e);
  }


  handleSelection(e: any) {
    this.selectedFiles = e;
    this.selectedBundleDetails = e?.fileids.map((a) => a.id);
    if (this.bIsfilePresent) {
      this.bIsfilePresent = false;
    }
    this.cdr.detectChanges();
  }

  getSelectedFiles(): choosedDocs[] {
    const cores = this.coreFiles.map((a) => {
      return { nBundledetailid: a, type: 'C' };
    });
    let folders = [],
      files = [];
    if (this.selectedFiles?.fileids?.length) {
      files = this.selectedFiles.fileids.map((a) => {
        return { nBundledetailid: a.id, type: 'F' };
      });
    }
    if (this.selectedFiles?.fldrids?.length) {
      folders = this.selectedFiles.fldrids.map((a) => {
        return { nBundleid: a.id, type: 'F' };
      });
    }
    return [...cores, ...files, ...folders];
  }

  async submit() {
    const jFiles = this.getSelectedFiles();

    if (!jFiles?.length) {
      if (this.presentSession?.cSType == 'F') {
        this.bIsfilePresent = true;
        return;
      }
      this.tost.openSnackBar('Please select at least one file', 'E');
      return;
    }
    await this.insertPresent(jFiles);
  }


  handleRedirect(nPresentid: string, nIndexid: string, jFiles: string[][]) {
    try {
      if (this.presentSession?.cSType == 'F' || this.presentSession?.cType == 'P') {

        // this.openIndexFile(nPresentid, nIndexid)
        jFiles.sort((a, b) => (a[0] === nIndexid ? -1 : b[0] === nIndexid ? 1 : 0));
        this.router.navigateByUrl(
          `/individual/doc/${encodeURIComponent(
            JSON.stringify([jFiles, this.nCaseid, nPresentid, nIndexid])
          )}`
        );
      } else if (
        this.presentSession?.cSType == 'C' ||
        this.presentSession?.cSType == 'W'
      ) {
        this.cm.gotoUrl('/present/core-case', {
          id: this.nCaseid,
          nPid: nPresentid,
        });
      }
    } catch (error) { }
  }

  openIndexFile(nPresentid, nIndexid) {
    if (!nIndexid) return;


    // const url = this.route.serializeUrl(
    //   this.route.createUrlTree(['/present/home', encodeURIComponent(JSON.stringify({ id: this.detail.nCaseid }))])
    // );
    // window.open(url, '_blank');
    this.cm.openedWindow = window.open(`${location.origin}/individual/doc/${encodeURIComponent(JSON.stringify([[[]], this.nCaseid, nPresentid, 0]))}`, '_blank');

  }

  async goToPresent() {
    await this.insertPresent([]);
  }

  async insertPresent(jFiles: choosedDocs[]) {
    const dataObj = {
      nCaseid: this.presentSession?.nCaseid,
      cStatus: ['W', 'C'].includes(this.presentSession?.cSType) ? 'B' : 'I',
      cName: this.presentSession?.cName,
      nContactid: this.nContactid,
      nTypeid: this.presentSession?.nTypeid,
      nSTypeid: this.presentSession?.nSTypeid,
      jUsers: this.presentSession?.jUsers,
      jFiles,
      nPresentid: this.nPresentid,
      nPCid: this.nPCid,
    };

    const res = await this.PSservice.insert(dataObj);
    if (res.msg == 1) {
      this.tost.openSnackBar('Document have been added successfully.');
      let files = jFiles.map(e => [e.nBundledetailid])
      this.handleRedirect(res.nPresentid, res.nBundledetailid, files);
    }
  }

  handlePresentHistory(event: any) {
    if (event?.event == 'PRESENT') {
      this.submit();
    }
    this.bShowPresentHistory = event;
    this.bIsfilePresent = false;
    this.cdr.detectChanges();
  }

  gotoFile() {
    this.handlePresentHistory(false);
  }
}
